export const ID=/^[A-Za-z0-9_-]{22}$/,SECRET=/^[A-Za-z0-9_-]{43}$/;const d=/^https?:\/\/[A-Za-z0-9.-]+(:\d{1,5})?$/,y=512;function l(e){if(typeof e!="string"||!d.test(e))throw new Error("not a site address");return e}function s(e,t,n){if(typeof t!="string"||!e.test(t))throw new Error(`not a ${n}`);return t}export function buildShare(e,t,n,r){return`${l(e)}${t.links.share}?c=${s(ID,n,"checklist id")}#k=${s(SECRET,r,"key")}`}export function buildEdit(e,t,n,r,o){return`${l(e)}${t.links.edit}?edit=${s(ID,n,"checklist id")}#k=${s(SECRET,r,"key")}&o=${s(SECRET,o,"owner token")}`}function c(e,t){if(!e)return null;const n={};for(const r of e.split("&")){const o=r.indexOf("=");if(o<1)return null;const a=r.slice(0,o),u=r.slice(o+1),i=f=>Object.prototype.hasOwnProperty.call(f,a);if(!i(t)||i(n)||!t[a].test(u))return null;n[a]=u}return Object.keys(n).length===Object.keys(t).length?n:null}function h(e){if(e&&typeof e=="object"){const{pathname:t,search:n,hash:r}=e;return[t,n,r].every(o=>typeof o=="string")?{pathname:t,search:n,hash:r}:null}if(typeof e!="string"||e.length>512)return null;try{const t=new URL(e);return t.protocol!=="https:"&&t.protocol!=="http:"||t.username||t.password?null:{pathname:t.pathname,search:t.search,hash:t.hash}}catch{return null}}const p=(e,t)=>e===t||e===`${t}index.html`;export function parseShare(e,t){const n=h(e);if(!n||!p(n.pathname,t.links.share))return null;const r=c(n.search.replace(/^\?/,""),{c:ID}),o=c(n.hash.replace(/^#/,""),{k:SECRET});return r&&o?{id:r.c,key:o.k}:null}export function parseEdit(e,t){const n=h(e);if(!n||!p(n.pathname,t.links.edit))return null;const r=c(n.search.replace(/^\?/,""),{edit:ID}),o=c(n.hash.replace(/^#/,""),{k:SECRET,o:SECRET});return r&&o?{id:r.edit,key:o.k,ownerToken:o.o}:null}export function withoutFragment(e){return`${e.pathname}${e.search}`}
